	'p_team_f4' => 'Dietitian',
	'p_team_f5' => 'Coordinator',
	'p_team_h1' => 'Our Clinical Team',
	'p_team_intro' => 'Our multidisciplinary clinical team in Harwell Green brings together endocrinologists, diabetes nurse educators, a dietitian, and our patient coordinator. We work collectively to deliver cohesive, compassionate care for adults across all stages of life.',
	'p_team_ix1' => 'Doctors',
	'p_team_ix2' => 'Nurse educators',
	'p_team_ix3' => 'Dietitian and coordinator',
	'p_team_p1_l' => 'Type 2 diabetes and long plans. Opened the clinic in 2011.',
	'p_team_p1_n' => 'Helena Varga',
	'p_team_p1_r' => 'Founder, endocrinologist',
	'p_team_p2_l' => 'Thyroid and pituitary conditions, and the in-clinic ultrasound.',
	'p_team_p2_n' => 'Tomas Okafor',
	'p_team_p2_r' => 'Endocrinologist',
